#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <iostream>
#include <cmath>
#include <vector>
#define TILE_DIM 16
#define N_GRID 240
#define PI_CONST 3.14159265358979323846
// -----------------------------------------------------------------------------
// KERNEL 1: Vectorized Sinc-Modulated Hybrid Kernel Construction
// -----------------------------------------------------------------------------
__global__ void build_hybrid_kernel_cuda(
    double* __restrict__ K,
    const double* __restrict__ r_grid,
    double lam, double Phi, double gamma, int N) 
{
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N && j < N) {
        if (i == j) {
            K[i * N + j] = 1.0;
        } else {
            double diff = r_grid[i] - r_grid[j];
            double abs_diff = fabs(diff);
            
            // Normalized Sinc: sin(pi * x) / (pi * x)
            double px = PI_CONST * diff;
            double sinc_val = sin(px) / px;
            // Howard-Comma residual decay factor
            double factor = 1.0 - lam / (1.0 + 0.33 * lam * Phi);
            double H_res = abs_diff * factor;
            double damping = exp(-gamma * H_res * H_res);
            double val = sinc_val * damping;
            K[i * N + j] = val;
        }
    }
}
// -----------------------------------------------------------------------------
// KERNEL 2: Tiled Shared-Memory Matrix Multiplication (C = A * B)
// -----------------------------------------------------------------------------
__global__ void matmul_tiled_cuda(
    const double* __restrict__ A,
    const double* __restrict__ B,
    double* __restrict__ C, int N) 
{
    __shared__ double tile_A[TILE_DIM][TILE_DIM];
    __shared__ double tile_B[TILE_DIM][TILE_DIM];
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int col = blockIdx.x * TILE_DIM + threadIdx.x;
    double acc = 0.0;
    for (int p = 0; p < (N + TILE_DIM - 1) / TILE_DIM; ++p) {
        if (row < N && p * TILE_DIM + threadIdx.x < N)
            tile_A[threadIdx.y][threadIdx.x] = A[row * N + p * TILE_DIM + threadIdx.x];
        else
            tile_A[threadIdx.y][threadIdx.x] = 0.0;
        if (col < N && p * TILE_DIM + threadIdx.y < N)
            tile_B[threadIdx.y][threadIdx.x] = B[(p * TILE_DIM + threadIdx.y) * N + col];
        else
            tile_B[threadIdx.y][threadIdx.x] = 0.0;
        __syncthreads();
        for (int k = 0; k < TILE_DIM; ++k) {
            acc += tile_A[threadIdx.y][k] * tile_B[k][threadIdx.x];
        }
        __syncthreads();
    }
    if (row < N && col < N) {
        C[row * N + col] = acc;
    }
}
